const REC=DATA.map(([id,g,e,t,min,srv,ings,steps])=>({id,g,e,t,min,srv,ings:ings.map(i=>({n:i[0],q:i[1],b:!!i[2]})),steps}));
const byG=g=>REC.filter(r=>r.g===g);
function hash(s){s=String(s||'x');let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return h>>>0}
function fill(r,name){const n=name||'este producto',sub=s=>String(s).replace(/\{producto\}/g,n);
  return {id:r.id,g:r.g,e:r.e,t:sub(r.t),min:r.min,srv:r.srv,ings:r.ings.map(i=>({n:sub(i.n),q:i.q,b:!!i.b})),steps:r.steps.map(sub)}}
function counted(ings){return (ings||[]).filter(i=>!i.b).length}

/* Puntuación de cada grupo a partir de etiquetas OFF, nombre, ingredientes y la categoría del usuario. */
function scores(p,catName){
  const tags=norm((p.catTags||[]).join(' ')+' '+(p.offCategories||''));
  const name=norm([p.name,p.brand].join(' '));
  const ings=norm(p.ingredients||'');
  const cat=norm(catName||'');
  const out={};
  for(const g of GROUPS){
    if(g.id==='otros')continue;
    let s=0;
    if(g.tag.test(tags))s+=5;
    if(g.name.test(name))s+=4;
    if(cat&&g.name.test(cat))s+=3;
    for(const [re,id] of CATMAP)if(id===g.id&&re.test(cat))s+=3;
    // los ingredientes solo desempate, para no clasificar un pan como «semillas» o «harina»
    if(s<4&&g.prio>=2&&g.name.test(ings))s+=1;
    if(s)out[g.id]=(out[g.id]||0)+s+g.prio/10;
  }
  // «bebida de avena» no es avena en copos; «pechuga de pavo» loncheada es embutido
  if((out.bebidasveg||0)>=4)delete out.avena;
  if(/lonchas|fiambre|cocido|york/.test(name)&&(out.embutido||0)>=3)delete out.carne;
  if(/\bpan\b/.test(name)&&(out.pan||0)>=4){delete out.harinas;if((out.frutossecos||0)<=out.pan)delete out.frutossecos}
  return Object.entries(out).sort((a,b)=>b[1]-a[1]||b[0].localeCompare(a[0]));
}
function poolFor(p,catName){
  const sc=scores(p,catName);
  if(!sc.length)return {groups:sc,pool:[],label:''};
  const top=sc[0][1];
  // hace falta una señal clara (nombre, etiqueta o categoría); si no, no se muestran recetas
  if(top<3)return {groups:sc,pool:[],label:''};
  const ids=[];const seen=new Set();
  const take=gid=>{for(const r of byG(gid))if(!seen.has(r.id)){seen.add(r.id);ids.push(r)}};
  for(const [gid,s] of sc)if(s>=Math.max(3,top-3))take(gid);
  if(ids.length<4)take('otros');
  const g=GROUPS.find(x=>x.id===sc[0][0]);
  return {groups:sc,pool:ids,label:g?g.label:''};
}
function forProduct(p,opts){
  opts=opts||{};const page=Math.max(0,+opts.page||0);
  const ev=opts.score!=null?{score:opts.score}:(root.SCORE&&p?root.SCORE.evaluate(p):{score:null});
  if(!p||p.src==='obf'||!ev||ev.score==null||ev.score<50)return {ok:false,reason:'no',recipes:[],total:0,page,label:''};
  const {pool,label,groups}=poolFor(p,opts.catName||'');
  if(!pool.length)return {ok:false,reason:'tipo',recipes:[],total:0,page,label:'',groups};
  const n=pool.length,off=(hash(p.code||p.id||p.name)+page*4)%n;
  const picked=[];for(let i=0;i<Math.min(4,n);i++)picked.push(pool[(off+i)%n]);
  const name=(p.name||'').trim()||'este producto';
  return {ok:true,recipes:picked.map(r=>fill(r,name)),total:n,page,label,group:groups[0]&&groups[0][0],groups};
}
const api={GROUPS,list:REC,count:REC.length,byG,scores,poolFor,forProduct,fill,counted,hash,norm};
if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.RECIPES=api;
